<script setup lang="ts">
import { uiText } from '@/i18n'

import {ref,onMounted,onBeforeUnmount} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {api,request} from '@/api/client'
import {vocabularyApi,type VocabularyBook} from '@/api/vocabulary'
import type {NoteSummaryView} from '@/types/api'
import {vaultOwners,unlockVault,saveVault,deleteVault,type Vault,type VaultNote,type OfflinePack} from '@/lib/offlineVault'
const owner=ref(0),owners=ref<number[]>([]),passphrase=ref(''),vault=ref<Vault>(),busy=ref(false),error=ref(''),message=ref(''),notes=ref<NoteSummaryView[]>([]),books=ref<VocabularyBook[]>([]),chosenNotes=ref<string[]>([]),chosenBook=ref(''),editing=ref<VaultNote>(),study=ref<OfflinePack>(),index=ref(0),answer=ref(''),revealed=ref(false),feedback=ref('')
const unsaved=ref(false)
let active=true,epoch=0
function leaveWarning(e:BeforeUnloadEvent){if(unsaved.value){e.preventDefault();e.returnValue=''}}
function requestLock(){if(!unsaved.value||confirm(uiText('修改尚未保存到本机，仍要锁定吗？')))lock()}
onBeforeRouteLeave(()=>!unsaved.value||confirm(uiText('修改尚未保存到本机，仍要离开吗？')))
async function task(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await work()}catch(e){if(active)error.value=(e as Error).message}finally{if(active)busy.value=false}}
async function persist(){if(vault.value){await saveVault(vault.value,passphrase.value);unsaved.value=false}}
function lock(){epoch++;unsaved.value=false;vault.value=undefined;editing.value=undefined;study.value=undefined;passphrase.value='';notes.value=[];books.value=[];chosenNotes.value=[];answer.value='';feedback.value='';message.value=''}
async function unlock(){await task(async()=>{if(!owner.value||passphrase.value.length<10)throw new Error('选择账户编号并输入至少 10 个字符的离线口令');const run=epoch;const loaded=await unlockVault(owner.value,passphrase.value);if(run!==epoch)return;if(!loaded){const user=await api.me();if(user.id!==owner.value)throw new Error('请登录这个账户后建立离线空间');vault.value={owner:owner.value,notes:[],packs:[]};await persist()}else vault.value=loaded;message.value='已解锁，内容仅保存在这台设备。'})}
async function prepare(){await task(async()=>{const user=await api.me();if(!vault.value||user.id!==vault.value.owner)throw new Error('请先登录并解锁同一个账户');[notes.value,books.value]=await Promise.all([user.permissions.includes('note:read')?api.notes():Promise.resolve([]),user.permissions.includes('vocabulary:use')?vocabularyApi.dashboard().then(d=>d.books):Promise.resolve([])]);message.value='选择最多 20 篇笔记和一份词书；每份词书准备最多 100 个词。'})}
async function download(){await task(async()=>{const data=vault.value;if(!data) return;const user=await api.me();if(user.id!==data.owner)throw new Error('登录账户已改变');if(chosenNotes.value.length>20)throw new Error('一次最多选择 20 篇笔记');for(const id of chosenNotes.value){const existing=data.notes.find(n=>n.id===id);if(existing?.dirty)throw new Error('选中的笔记有离线修改，请先同步');const n=await api.note(id);const saved={id:n.id,title:n.title,body:n.body,revision:n.revision,contentFormat:n.contentFormat,dirty:false};if(existing)Object.assign(existing,saved);else data.notes.push(saved)}if(chosenBook.value){const pack=await request<OfflinePack>('/vocabulary/offline',{method:'POST',body:JSON.stringify({bookId:chosenBook.value})});pack.attempts=[];data.packs.push(pack)}await persist();const registration=await navigator.serviceWorker.register('/offline-sw.js',{scope:'/'});const worker=registration.installing||registration.waiting;if(worker&&worker.state!=='activated'){await new Promise<void>((resolve,reject)=>{const timer=setTimeout(()=>{worker.removeEventListener('statechange',check);reject(new Error('资料已保存，应用缓存尚未完成，请联网重试下载'))},30000);function check(){if(worker!.state==='activated'||worker!.state==='redundant'){clearTimeout(timer);worker!.removeEventListener('statechange',check);worker!.state==='activated'?resolve():reject(new Error('应用缓存失败，请联网重试'))}}worker.addEventListener('statechange',check);check()})}await navigator.serviceWorker.ready;chosenNotes.value=[];chosenBook.value='';message.value='资料已加密保存，应用缓存已就绪。收藏本页，断网后可继续使用。'})}
async function saveNote(){await task(async()=>{if(editing.value)editing.value.dirty=true;await persist();message.value='离线修改已加密保存，联网后可同步。'})}
async function sync(){await task(async()=>{const data=vault.value;if(!data)return;const user=await api.me();if(user.id!==data.owner)throw new Error('请登录离线内容所属的账户后再同步');let saved=0,conflicts=0;for(const n of data.notes.filter(n=>n.dirty)){try{const server=await api.note(n.id);if(server.revision!==n.revision){if(server.body===n.body&&server.title===n.title){n.revision=server.revision;n.dirty=false;continue}n.conflict=true;conflicts++;continue}const updated=await api.updateNote(n.id,{baseRevision:n.revision,title:n.title,body:n.body,contentFormat:n.contentFormat});n.revision=updated.revision;n.dirty=false;n.conflict=false;saved++}catch(e){n.conflict=true;conflicts++}}for(const pack of data.packs){if(!pack.attempts.length)continue;const result=await request<{recorded:number;conflicts:number}>(`/vocabulary/offline/${pack.id}/sync`,{method:'POST',body:JSON.stringify({attempts:pack.attempts})});saved+=result.recorded;conflicts+=result.conflicts;pack.attempts=[]}await persist();message.value=`已同步 ${saved} 项；${conflicts} 项保留线上进度或需要处理。离线答题计入练习统计，不替代独立回忆测验。`})}
async function copyConflict(n:VaultNote){await task(async()=>{const user=await api.me();if(user.id!==vault.value?.owner)throw new Error('请登录原账户');n.copyId ||= crypto.randomUUID();await persist();const created=await api.createNote({clientId:n.copyId,title:n.title+' · 离线副本',body:n.body,contentFormat:n.contentFormat});n.id=created.id;n.title=created.title;n.revision=created.revision;n.copyId=undefined;n.dirty=false;n.conflict=false;await persist();message.value='已保存为独立笔记，原笔记保留线上版本。'})}
async function grade(){await task(async()=>{const pack=study.value,w=pack?.items[index.value];if(!pack||!w||!answer.value.trim())return;pack.attempts=pack.attempts.filter(a=>a.wordId!==w.id);pack.attempts.push({wordId:w.id,text:answer.value.trim(),revealed:revealed.value,answeredAt:new Date().toISOString()});feedback.value=answer.value.trim().toLowerCase()===w.term.toLowerCase()?'答对了':'正确拼写：'+w.term;await persist()})}
function next(){if(!study.value)return;index.value=(index.value+1)%study.value.items.length;answer.value='';revealed.value=false;feedback.value=''}
function exportNote(n:VaultNote){const url=URL.createObjectURL(new Blob([n.body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='offline-note.'+(n.contentFormat==='HTML'?'html':'md');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function erase(){if(!confirm(uiText('删除此设备上的离线内容？尚未同步的修改也会删除。')))return;await task(async()=>{await deleteVault(owner.value);lock();owners.value=(await vaultOwners()).map(Number)})}
function changed(){lock()}
onMounted(async()=>{owners.value=(await vaultOwners()).map(Number);try{const user=await api.me();if(active)owner.value=user.id}catch{owner.value=owners.value[0]||0}window.addEventListener('storage',changed);window.addEventListener('beforeunload',leaveWarning)})
onBeforeUnmount(()=>{active=false;lock();window.removeEventListener('storage',changed);window.removeEventListener('beforeunload',leaveWarning)})
</script>
<template><main class="offline-page"><header><RouterLink to="/app/learning">{{ uiText('← 返回学习空间') }}</RouterLink><p class="page-kicker">OFFLINE LEARNING</p><h1>{{ uiText('断网，也能继续。') }}</h1><p>{{ uiText('选择资料保存在此设备，联网后同步到原账户。离线口令无法找回，请妥善记住。') }}</p></header>
<p v-if="error" class="inline-alert inline-alert--error" role="alert">{{ uiText(error) }}</p><p v-if="message" role="status">{{message}}</p>
<form v-if="!vault" class="offline-unlock" @submit.prevent="unlock"><label>{{ uiText('账户编号') }}<input v-model.number="owner" type="number" min="1" class="field-input" required/></label><label>{{ uiText('离线口令') }}<input v-model="passphrase" type="password" minlength="10" autocomplete="off" class="field-input" required/></label><p>{{ uiText('已有离线账户：') }}{{owners.join('、')||uiText('暂无')}}{{ uiText('。首次创建需要在线登录。') }}</p><button class="button button--dark" :disabled="busy">{{ uiText('解锁 / 建立离线空间') }}</button></form>
<template v-else><div class="research-actions"><button class="button button--ghost" :disabled="busy" @click="prepare">{{ uiText('选择离线资料') }}</button><button class="button button--dark" :disabled="busy" @click="sync">{{ uiText('联网同步') }}</button><button class="button button--ghost" :disabled="busy" @click="requestLock">{{ uiText('锁定') }}</button><button class="button button--ghost" :disabled="busy" @click="erase">{{ uiText('清除本机副本') }}</button></div>
<details v-if="notes.length||books.length" open class="offline-picker"><summary>{{ uiText('准备资料') }}</summary><label v-for="n in notes" :key="n.id"><input v-model="chosenNotes" type="checkbox" :value="n.id"/> {{n.title}}</label><select v-model="chosenBook" class="field-input"><option value="">{{ uiText('不新增词书') }}</option><option v-for="b in books" :key="b.id" :value="b.id">{{b.title}}</option></select><button class="button button--dark" :disabled="busy" @click="download">{{ uiText('加密下载所选资料') }}</button></details>
<div class="offline-columns"><section><h2>{{ uiText('离线笔记') }}</h2><p v-if="!vault.notes.length">{{ uiText('尚未准备笔记。') }}</p><article v-for="n in vault.notes" :key="n.id"><button class="result-title" @click="editing=n">{{n.title}}</button><small>{{n.dirty?uiText('待同步'):uiText('已保存')}}</small><template v-if="n.conflict"><p>{{ uiText('线上版本发生变化或暂不可访问，本地内容已保留。') }}</p><button class="button button--ghost" :disabled="busy" @click="copyConflict(n)">{{ uiText('另存为新笔记') }}</button></template><button class="table-action" @click="exportNote(n)">{{ uiText('导出') }}</button></article><h2>{{ uiText('离线词汇') }}</h2><button v-for="p in vault.packs" :key="p.id" class="button button--ghost" @click="study=p;index=0;answer='';feedback='';revealed=false">{{p.items.length}} {{ uiText('个词 ·') }} {{p.attempts.length}} {{ uiText('条待同步练习') }}</button><p class="research-hint">{{ uiText('同步包有效期 7 天。同一天同一单词的离线练习只计一次；线上进度有变化时保留线上进度。') }}</p></section>
<section><form v-if="editing" @submit.prevent="saveNote"><input :aria-label="uiText('离线笔记标题')" v-model="editing.title" class="field-input" maxlength="180" required :disabled="busy" @input="editing.dirty=true;unsaved=true"/><textarea :aria-label="uiText('离线笔记正文')" v-model="editing.body" class="field-input offline-editor" maxlength="100000" :disabled="busy" @input="editing.dirty=true;unsaved=true"/><button class="button button--dark" :disabled="busy">{{ uiText('保存本地修改') }}</button><p>{{ uiText('以 Markdown / HTML 源码编辑；离线不执行 HTML 或脚本。') }}</p></form><form v-if="study?.items[index]" class="offline-word" @submit.prevent="grade"><small>{{index+1}} / {{study.items.length}}</small><h2>{{study.items[index].meaning}}</h2><p>{{study.items[index].translation}}</p><input v-model="answer" class="field-input" autocomplete="off" :placeholder="uiText('回忆英文拼写')" maxlength="160" required :disabled="busy"/><button type="button" class="table-action" @click="revealed=true">{{ uiText('查看单词') }}</button><p v-if="revealed">{{study.items[index].term}} {{study.items[index].ipa}}<br/>{{study.items[index].example}}</p><p role="status">{{feedback}}</p><div class="research-actions"><button class="button button--dark" :disabled="busy">{{ uiText('检查并保存') }}</button><button type="button" class="button button--ghost" :disabled="busy" @click="next">{{ uiText('下一个') }}</button></div></form></section></div></template></main></template>
<style scoped>.offline-page{max-width:1120px;margin:auto;padding:48px 32px;min-height:100vh}header{margin-bottom:36px}h1{font-size:38px;font-weight:500}header p{color:var(--muted)}.offline-unlock{max-width:460px;display:grid;gap:18px}.offline-columns{display:grid;grid-template-columns:300px minmax(0,1fr);gap:36px;margin-top:32px}.offline-columns article{padding:18px 0;border-bottom:1px solid var(--line)}small{display:block;color:var(--muted);margin:8px 0}.offline-picker{margin-top:24px}.offline-picker label{display:block;padding:6px}.offline-picker select{margin:16px 0;max-width:400px}.offline-editor{margin:14px 0;min-height:400px;font-family:monospace}.offline-word{padding:30px 0;border-top:1px solid var(--line);margin-top:24px}.research-actions{flex-wrap:wrap}@media(max-width:800px){.offline-columns{grid-template-columns:1fr}}</style>
